<?php
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/../conexion.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'delete') {
    $delete = $conexion->prepare('DELETE FROM contacto WHERE id=?'); $delete->execute([(int)($_POST['id'] ?? 0)]);
    header('Location: mensajes.php?eliminado=1'); exit;
}
$error = '';
try { $allMessages = $conexion->query('SELECT * FROM contacto ORDER BY id DESC')->fetchAll(); }
catch (Throwable $e) { $allMessages = []; $error = 'No encontramos la tabla de mensajes. Revisa el esquema de contacto.'; }
$query = trim($_GET['q'] ?? ''); $kind = $_GET['tipo'] ?? '';
$messages = array_values(array_filter($allMessages, static function ($message) use ($query, $kind) {
    $text = ($message['nombre'] ?? '') . ' ' . ($message['email'] ?? '') . ' ' . ($message['mensaje'] ?? '');
    return ($query === '' || stripos($text, $query) !== false) && ($kind === '' || ($message['tipo_mensaje'] ?? '') === $kind);
}));
$kinds = array_values(array_unique(array_filter(array_column($allMessages, 'tipo_mensaje'))));
$avatar = !empty($_SESSION['foto_perfil']) ? '../' . $_SESSION['foto_perfil'] : 'https://ui-avatars.com/api/?name=' . rawurlencode($_SESSION['usuario_nombre'] ?? 'Admin') . '&background=0876ea&color=fff';
function h($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
function initialOf($value) { return preg_match('/^./us', (string)$value, $match) ? strtoupper($match[0]) : '?'; }
?>
