<aside class="admin-sidebar"><a class="admin-brand" href="../index.php">SPORT<span>MAX</span></a><p class="admin-label">Administración</p><nav class="admin-nav"><a href="dashboard.php"><span class="ico">◈</span>Resumen</a><a href="productos.php"><span class="ico">▣</span>Productos</a><a href="usuarios.php"><span class="ico">♙</span>Usuarios</a><a class="active" href="mensajes.php"><span class="ico">✉</span>Mensajes</a><a href="../perfil.php"><span class="ico">◉</span>Mi perfil</a></nav><div class="sidebar-account"><img src="<?= h($avatar) ?>" alt=""><div><strong><?= h($_SESSION['usuario_nombre'] ?? 'Admin') ?></strong><small>Administrador</small></div><a href="../logout.php">↗</a></div></aside>
