<?php if ($error): ?><div class="error-note" role="alert"><?= h($error) ?></div><?php elseif (isset($_GET['eliminado'])): ?><div class="success-note">El mensaje se eliminó de la bandeja.</div><?php endif; ?>
<section class="stats-row"><article class="mini-stat"><span class="stat-ico">✉</span><div><small>Mensajes recibidos</small><strong><?= count($allMessages) ?></strong></div></article><article class="mini-stat"><span class="stat-ico">⌕</span><div><small>Coincidencias</small><strong><?= count($messages) ?></strong></div></article><article class="mini-stat"><span class="stat-ico">◉</span><div><small>Tipos de mensaje</small><strong><?= count($kinds) ?></strong></div></article><article class="mini-stat"><span class="stat-ico">↗</span><div><small>Respuesta directa</small><strong>Email</strong></div></article></section>
<div class="heading-row"><div><h2>Bandeja de entrada</h2><p>Selecciona responder para abrir tu aplicación de correo.</p></div></div><section class="admin-card"><div class="toolbar"><form class="search-form" method="get"><input type="search" name="q" value="<?= h($query) ?>" placeholder="Buscar nombre, correo o mensaje"><select name="tipo"><option value="">Todos los tipos</option><?php foreach ($kinds as $messageKind): ?><option value="<?= h($messageKind) ?>" <?= $kind === $messageKind ? 'selected' : '' ?>><?= h($messageKind) ?></option><?php endforeach; ?></select><button class="admin-button-secondary">Filtrar</button></form></div><?php if (!$messages): ?><div class="admin-empty"><strong><?= $allMessages ? 'No hay coincidencias' : 'Tu bandeja está despejada' ?></strong><?= $allMessages ? 'Prueba otros términos de búsqueda.' : 'Los mensajes enviados desde la tienda aparecerán aquí.' ?></div><?php else: ?><div class="message-grid"><?php foreach ($messages as $message): ?><article class="admin-card message-card"><div class="message-top"><div class="message-person"><span class="message-avatar"><?= h(mb_strtoupper(mb_substr($message['nombre'] ?? '?', 0, 1, 'UTF-8'), 'UTF-8')) ?></span><div><strong><?= h($message['nombre']) ?></strong><small><?= h($message['email']) ?></small></div></div><span class="message-kind"><?= h($message['tipo_mensaje'] ?? 'General') ?></span></div><p class="message-body"><?= h($message['mensaje']) ?></p><footer class="message-foot"><a class="admin-button-secondary" href="mailto:<?= h($message['email']) ?>?subject=Sport%20Max%20-%20respuesta%20a%20tu%20mensaje">↗ Responder</a><form method="post" onsubmit="return confirm('¿Eliminar este mensaje?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$message['id'] ?>"><button class="admin-button-danger">Eliminar</button></form></footer></article><?php endforeach; ?></div><?php endif; ?></section><footer class="admin-footer">SPORT MAX · Atención al cliente</footer></main></body></html>
